"""Convert instrument readings written as text, such as "12 ft" or "-40 C"."""

import re

from unitconv.scales import LENGTH, MASS, convert
from unitconv.temperature import convert_temperature

READING = re.compile(r"\s*([-+]?\d+(?:\.\d+)?)\s*([A-Za-z]+)\s*")


def parse_reading(text: str) -> tuple[float, str]:
    """Split a reading into its number and its unit symbol."""
    match = READING.fullmatch(text)
    if match is None:
        raise ValueError(f"cannot parse reading: {text!r}")
    return float(match.group(1)), match.group(2)


def convert_reading(text: str, dst: str) -> float:
    """Convert a reading such as "12 ft" to the unit dst."""
    value, src = parse_reading(text)
    for table in (LENGTH, MASS):
        if src in table:
            return convert(value, src, dst, table)
    return convert_temperature(value, src, dst)

