def median(scores: list[float]) -> float:
    """Middle score; the mean of the two middle scores for an even count."""
    ordered = sorted(scores)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

